    }

    /**
     * Sets email_notification_schedule
     *
     * @param string|null $email_notification_schedule Email notification of transactions
     *
     * @return self
     */
    public function setEmailNotificationSchedule($email_notification_schedule)
    {
        $allowedValues = $this->getEmailNotificationScheduleAllowableValues();
        if (!is_null($email_notification_schedule) && !in_array($email_notification_schedule, $allowedValues, true)) {
            throw new \InvalidArgumentException(
                sprintf(
                    "Invalid value '%s' for 'email_notification_schedule', must be one of '%s'",
                    $email_notification_schedule,
                    implode("', '", $allowedValues)
                )
            );
        }
        $this->container['email_notification_schedule'] = $email_notification_schedule;

        return $this;
    }

